[PostHandlerFor(classStr(InventLocationWHSProcessEnablementService), methodStr(InventLocationWHSProcessEnablementService, enableWarehouseProcesses))]
public static void InventLocationWHSProcessEnablementService_Post_enableWarehouseProcesses(XppPrePostArgs args)
{
    InventLocationWHSProcessEnablementContract contract = args.getArg(identifierStr(_dataContract)) as InventLocationWHSProcessEnablementContract;

    container queryContainer = SysOperationHelper::base64Decode(contract.whsProcessEnablementRequestQuery());

    if (!queryContainer)
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    QueryRun queryRun = new QueryRun(new Query(queryContainer));

    while (queryRun.next())
    {
        InventLocationWHSProcessEnablementRequest enablementRequest = queryRun.get(tableNum(InventLocationWHSProcessEnablementRequest));

        InventLocation inventLocation = InventLocation::find(enablementRequest.InventLocationId);
        if(inventLocation.WHSEnabled)
        {
            MobInventLocationsPickReceiveTypes pickReceiveInfo = MobInventLocationsPickReceiveTypes::find(enablementRequest.InventLocationId, true);
            if(pickReceiveInfo)
            {
                pickReceiveInfo.delete();
            }
        }
    }
}
